import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg['resolvedVersion']
        result[pname] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

print('Baseline:', json.dumps(b, indent=2))
print('After:', json.dumps(a, indent=2))

# Check for differences
diffs = []
for proj in set(list(b.keys()) + list(a.keys())):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in set(list(bp.keys()) + list(ap.keys())):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            diffs.append((proj, pkg, bv, av))

if diffs:
    print('DIFFERENCES FOUND:')
    for d in diffs:
        print(f'  {d}')
else:
    print('NO DIFFERENCES - conversion is version-neutral')
